private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Step 1: Find the first node on the outer face that satisfies the predicate
    Node current = start;
    while (!predicate.apply(current) && !current.isSameNode(stop)) {
        current = current.getNext(dir);
    }

    // Step 2: If the first node does not satisfy the predicate, return a circulator to the stop node
    if (!predicate.apply(current)) {
        return new OuterFaceCirculator(current, stop, dir);
    }

    // Step 3: Otherwise, find the first node that does not satisfy the predicate, starting from the second node
    current = current.getNext(dir);
    while (predicate.apply(current) && !current.isSameNode(stop)) {
        current = current.getNext(dir);
    }

    // Step 4: Return a circulator to the last node that satisfies the predicate
    return new OuterFaceCirculator(current, stop, dir);
}
