public static String applyRelativePath(String path,String relativePath){
    // Split the path into components
    String[] pathComponents = path.split("/");
    // Split the relative path into components
    String[] relativePathComponents = relativePath.split("/");
    // Check if the relative path is an absolute path, and if so, return it directly
    if(relativePathComponents[0].equals("")){
        return relativePath;
    }
    // Build the new path by iterating over both path and relative path components
    List<String> newPathComponents = new ArrayList<>();
    int i = 0;
    int j = 0;
    while(i < pathComponents.length && j < relativePathComponents.length){
        if(relativePathComponents[j].equals("..")){
            // Handle ".." as a signal to move up one directory
            i--;
            j++;
        }else if(relativePathComponents[j].equals(".")){
            // Handle "." as a signal to do nothing
            j++;
        }else{
            // Add the current component to the new path
            newPathComponents.add(relativePathComponents[j]);
            i++;
            j++;
        }
    }
    // Add any remaining components from the path
    while(i < pathComponents.length){
        newPathComponents.add(pathComponents[i]);
        i++;
    }
    // Join the components together with slashes
    String newPath = String.join("/", newPathComponents);
    return newPath;
}

