public static String[] toNoNullStringArray(Object[] array) {
    // Check for null and empty array
    if (array == null || array.length == 0) {
        return new String[0];
    }

    // Create an array of the right size
    String[] noNullArray = new String[array.length];

    // Copy elements from the original array to the new array, skipping null elements
    int writeIndex = 0;
    for (int readIndex = 0; readIndex < array.length; readIndex++) {
        Object element = array[readIndex];
        if (element != null) {
            noNullArray[writeIndex++] = (String) element;
        }
    }

    // If the new array has the same length as the original, return the original array
    // Otherwise, return the new array with the null elements removed
    return writeIndex == array.length ? array : noNullArray;
}

